# Built from the schema bytes alone; does not import the author's checker.
import json,re,sys
S='/tmp/opensip-design-corrections/candidate-subject.v7/docs/coop/design-corrections/'
sch=json.load(open(S+'foundation/identity-schemas.v2.json'))

HEX64=[r'^[0-9a-f]{64}$',r'^[0-9a-f]{64}\Z']
def is64(node):
    if not isinstance(node,dict): return False
    p=node.get('pattern')
    if p and re.fullmatch(r'\^\[0-9a-f\]\{64\}\$',p): return True
    if node.get('type')=='string' and node.get('minLength')==64 and node.get('maxLength')==64: return True
    return False
def isPrefixed(node):
    p=node.get('pattern') if isinstance(node,dict) else None
    return bool(p) and '[0-9a-f]{64}' in p and p!='^[0-9a-f]{64}$'

found=[];prefixed=[]
