    if isinstance(n,dict):
        if is64(n): found.append((path,n))
        elif isPrefixed(n): prefixed.append((path,n.get('pattern')))
        for k,v in n.items(): walk(v,path+'/'+k)
    elif isinstance(n,list):
        for i,v in enumerate(n): walk(v,path+'/'+str(i))
walk(sch,'')
ann=[p for p,n in found if 'x-opensip-digest' in n]
unann=[p for p,n in found if 'x-opensip-digest' not in n]
reps={}
retn={}
for p,n in found:
    a=n.get('x-opensip-digest')
