out={'total64HexFields':len(found),'annotated':len(ann),'unannotated':unann,
     'representationCounts':{k:len(v) for k,v in reps.items()},
     'retentionCounts':{k:len(v) for k,v in retn.items()},
     'prefixedHexFields':len(prefixed),
